// Pseudo: contract validation and upsert
function upsertEvent(event, registry) {
  const contract = registry.getContract(event.version, event.schemaKey);
  if (!contract.validate(event)) throw new Error('Contract violation');
  // perform idempotent merge into Iceberg
  mergeIntoIceberg(event, contract.primaryKey);
}
```

